-- =====================================================
-- CASE: Recurrent Migraine
-- =====================================================
INSERT INTO sca_cases (
  title, category, category_code, scenario, patient_info, case_notes, actor_info, actor_behaviour,
  case_type, time_limit, difficulty, key_points, model_answer, is_pro, published, marking_criteria
) VALUES (
  'Recurrent Migraine',
  'Neurology',
  'FC-001',
  'You are a GP. A 34-year-old woman, Ms. Rachel Holt, has booked a face-to-face appointment. She has had recurrent headaches for 2 years and wants to discuss prevention.',
  '{"name": "Ms. Rachel Holt", "age": 34, "gender": "Female"}',
  '{"patient": "Ms. Rachel Holt", "age": 34, "gender": "Female", "pmh": "None", "medications": "Sumatriptan PRN", "allergies": "None", "social_summary": "Teacher, non-smoker", "family_summary": "Mother has migraine"}',
  '{"opening_statement": "Doctor, I get these awful headaches every few weeks. The triptan helps when I take it early but I want to know if there is something to prevent them.", "freely_given_history": {"presenting_complaint": "Recurrent headaches, throbbing, one side, with nausea. Last 4–24 hours.", "psychosocial_impact": "Missing work sometimes.", "ice": {"ideas": "Worried it might be something serious", "concerns": "Wants to reduce frequency", "expectations": "Hopes for preventive treatment"}}, "history_on_direct_questioning": {"frequency": "2–3 per month", "triggers": "Stress, lack of sleep", "aura": "No visual disturbance", "red_flags": "No sudden onset, no worst ever, no fever"}}',
  'ANXIOUS but articulate. Wants a clear plan. If doctor discusses prevention (e.g. propranolol, topiramate, lifestyle), show interest.',
  'full', 720, 'medium',
  ARRAY['Migraine diagnosis', 'Trigger and diary', 'Acute vs preventive treatment', 'Lifestyle', 'Safety-netting'],
  '## Model Approach\n\n**Key:** Confirm migraine (history, red flags). Discuss trigger diary, lifestyle (sleep, stress). Acute: triptan, NSAID. Preventive: propranolol or topiramate if frequent. Safety-net: sudden/worst ever headache, focal signs.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established presenting complaint clearly", "Explored headache characteristics and frequency", "Obtained relevant past medical history", "Obtained drug history", "Explored ICE thoroughly", "Assessed red flags", "Obtained family history"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["Considered migraine vs other headache", "Discussed acute and preventive options", "Provided clear safety-netting", "Arranged follow-up", "Documented appropriately"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Demonstrated empathy", "Used clear language", "Listened actively", "Involved patient in decisions", "Maintained professional manner"]}}'
);

-- =====================================================
-- CASE: New Type 2 Diabetes
-- =====================================================
INSERT INTO sca_cases (
  title, category, category_code, scenario, patient_info, case_notes, actor_info, actor_behaviour,
  case_type, time_limit, difficulty, key_points, model_answer, is_pro, published, marking_criteria
) VALUES (
  'New Type 2 Diabetes',
  'Endocrinology',
  'FC-002',
  'You are a GP. A 52-year-old man, Mr. Ian Moss, has been told his HbA1c is 58 (diabetes range). He has come to discuss what this means and what to do next.',
  '{"name": "Mr. Ian Moss", "age": 52, "gender": "Male"}',
  '{"patient": "Mr. Ian Moss", "age": 52, "gender": "Male", "pmh": "Hypertension", "medications": "Amlodipine 5mg", "allergies": "None", "social_summary": "Office job, BMI 31", "family_summary": "Father had diabetes"}',
  '{"opening_statement": "The nurse said my sugar is high and I have diabetes. I feel fine – do I really need to do anything?", "freely_given_history": {"presenting_complaint": "No symptoms. Shocked by diagnosis.", "ice": {"ideas": "Worried about tablets and complications", "concerns": "Can he reverse it?", "expectations": "Wants clear advice"}}, "history_on_direct_questioning": {"diet": "Eats takeaways 3–4 times per week", "exercise": "Little", "smoking": "No", "alcohol": "10–15 units/week"}}',
  'Slightly defensive but willing to listen. Responds well to clear, non-judgmental advice.',
  'full', 720, 'medium',
  ARRAY['Explain diagnosis', 'Lifestyle first', 'Metformin', 'Retinal and foot check', 'Follow-up'],
  '## Model Approach\n\n**Key:** Explain T2DM and importance of control. Lifestyle: diet, weight, exercise. Metformin first line. Arrange retinal screening and foot check. Diabetes education. Follow-up.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established understanding of diagnosis", "Explored lifestyle", "Obtained PMH and medications", "Explored ICE", "Assessed cardiovascular risk"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["Explained diagnosis and targets", "Discussed lifestyle and metformin", "Arranged retinal and foot check", "Arranged follow-up", "Documented appropriately"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Demonstrated empathy", "Non-judgmental approach", "Clear explanation", "Involved patient in plan"]}}'
),

('Chronic Low Back Pain', 'Musculoskeletal', 'FC-003',
  'You are a GP. A 48-year-old man, Mr. David Peel, has had low back pain for 3 months. He has tried physio and ibuprofen. Wants to know what else can be done.',
  '{"name": "Mr. David Peel", "age": 48, "gender": "Male"}',
  '{"patient": "Mr. David Peel", "age": 48, "gender": "Male", "pmh": "None", "medications": "Ibuprofen PRN", "allergies": "None", "social_summary": "Desk job", "family_summary": "None"}',
  '{"opening_statement": "My back has been killing me for months. Physio helped a bit but it keeps coming back. Is there anything stronger or do I need a scan?", "freely_given_history": {"presenting_complaint": "Central low back pain, no leg symptoms.", "ice": {"ideas": "Worried about disc", "concerns": "Wants to work", "expectations": "Scan or stronger treatment"}}, "history_on_direct_questioning": {"red_flags": "No cauda equina, no weight loss", "work": "Desk job"}}',
  'Frustrated but cooperative. Responds to clear explanation of NICE back pain pathway.',
  'full', 720, 'easy',
  ARRAY['NICE back pain', 'Red flags', 'Physio and analgesia', 'Avoid routine imaging', 'Safety-netting'],
  '## Model Approach\n\n**Key:** Exclude red flags. NICE: continue physio, analgesia; avoid routine imaging. Reassure. Safety-net.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established presenting complaint", "Explored pain and red flags", "Obtained PMH", "Explored ICE"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["Applied NICE back pain pathway", "Avoided routine imaging", "Safety-netting", "Follow-up"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Empathy", "Clear explanation", "Involved patient"]}}'
),

('Request for Sleeping Tablets', 'Mental Health', 'FC-004',
  'You are a GP. A 58-year-old woman, Mrs. Sandra Quick, has had insomnia for 2 months. She wants something to help her sleep. Stressed about family issues.',
  '{"name": "Mrs. Sandra Quick", "age": 58, "gender": "Female"}',
  '{"patient": "Mrs. Sandra Quick", "age": 58, "gender": "Female", "pmh": "None", "medications": "None", "allergies": "None", "social_summary": "Caring for ill mother", "family_summary": "None"}',
  '{"opening_statement": "I just need something to help me sleep. I lie there for hours. I have heard zopiclone works.", "freely_given_history": {"presenting_complaint": "Difficulty falling asleep, stress.", "ice": {"ideas": "Wants tablets", "concerns": "Worried about dependency", "expectations": "Short-term help"}}, "history_on_direct_questioning": {"caffeine": "Tea until 8pm", "routine": "Variable", "mood": "Stressed, not low"}}',
  'Anxious, keen for a quick fix. Receptive to sleep hygiene if offered with short-term option.',
  'full', 720, 'easy',
  ARRAY['Sleep hygiene', 'CBT-I', 'Short-term hypnotic only if needed', 'Safety-netting'],
  '## Model Approach\n\n**Key:** Sleep hygiene, address stress. CBT-I first line. Hypnotic only short-term if severe. Safety-net.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established complaint", "Explored sleep and stress", "Explored ICE"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["Sleep hygiene", "CBT-I", "Limited hypnotic", "Safety-netting"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Empathy", "Clear advice"]}}'
),

('Child with Earache', 'Paediatrics', 'FC-005',
  'You are a GP. The mother of 4-year-old Tom has brought him in with earache for 2 days. He has had a cold. No fever today. Drinking and playing.',
  '{"name": "Tom", "age": 4, "gender": "Male"}',
  '{"patient": "Tom", "age": 4, "gender": "Male", "pmh": "None", "medications": "None", "allergies": "None", "social_summary": "Nursery", "family_summary": "None"}',
  '{"opening_statement": "He has been pulling his ear and crying. I gave him Calpol. Should he have antibiotics?", "freely_given_history": {"presenting_complaint": "Earache, cold.", "ice": {"ideas": "Ear infection", "concerns": "Wants to avoid antibiotics if possible", "expectations": "Clear advice"}}, "history_on_direct_questioning": {"fever": "Had fever, better today", "feeding": "Drinking", "red_flags": "No rash, no neck stiffness"}}',
  'Mother anxious but informed. Wants clear advice.',
  'full', 720, 'easy',
  ARRAY['Acute otitis media', 'Watchful waiting vs antibiotics', 'Pain relief', 'Safety-netting'],
  '## Model Approach\n\n**Key:** AOM – most resolve without antibiotics. Pain relief (paracetamol/ibuprofen). Safety-net: worsening, fever, rash. Antibiotics if systemically unwell or high risk.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established complaint", "Explored symptoms and red flags", "Explored ICE"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["AOM management", "Pain relief", "Safety-netting"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Empathy", "Parental reassurance"]}}'
),

('Hypertension Review', 'Cardiovascular', 'FC-006',
  'You are a GP. A 62-year-old man, Mr. Frank Reid, is here for his annual hypertension review. His home readings have been 145–155/88–92. On amlodipine 5mg.',
  '{"name": "Mr. Frank Reid", "age": 62, "gender": "Male"}',
  '{"patient": "Mr. Frank Reid", "age": 62, "gender": "Male", "pmh": "Hypertension, T2DM", "medications": "Amlodipine 5mg, Metformin", "allergies": "None", "social_summary": "Retired, ex-smoker", "family_summary": "Father stroke at 70"}',
  '{"opening_statement": "The nurse said my blood pressure is still a bit high. Do I need another tablet?", "freely_given_history": {"presenting_complaint": "BP above target.", "ice": {"ideas": "Worried about stroke", "concerns": "More tablets", "expectations": "Clear plan"}}, "history_on_direct_questioning": {"compliance": "Takes regularly", "lifestyle": "Trying to lose weight", "symptoms": "None"}}',
  'Cooperative. Wants to avoid more medication if possible but will take if needed.',
  'full', 720, 'easy',
  ARRAY['BP target', 'Lifestyle', 'Step-up if needed', 'CV risk', 'Follow-up'],
  '## Model Approach\n\n**Key:** Confirm BP target (e.g. <140/90). Lifestyle. Consider adding ACEi/ARB if above target. CV risk discussion. Follow-up.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established BP and compliance", "Explored lifestyle", "Explored ICE"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["BP target", "Step-up if needed", "Follow-up"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Clear explanation", "Involved patient"]}}'
),

('Request for Sick Note', 'General Practice', 'FC-007',
  'You are a GP. A 29-year-old woman, Ms. Helen Stone, is asking for a fit note for 2 weeks off work. She has been low and anxious. Has had time off already.',
  '{"name": "Ms. Helen Stone", "age": 29, "gender": "Female"}',
  '{"patient": "Ms. Helen Stone", "age": 29, "gender": "Female", "pmh": "Anxiety", "medications": "Sertraline 50mg", "allergies": "None", "social_summary": "Office job", "family_summary": "None"}',
  '{"opening_statement": "I need a sick note for work. I have been signed off for 2 weeks already but I am not ready to go back. My mood is still low.", "freely_given_history": {"presenting_complaint": "Low mood, anxiety.", "ice": {"ideas": "Needs more time", "concerns": "Work pressure", "expectations": "2 more weeks"}}, "history_on_direct_questioning": {"mood": "Low", "risk": "No suicidal ideation", "support": "CBT waiting list"}}',
  'Anxious, defensive about work. Wants note but also support.',
  'full', 720, 'easy',
  ARRAY['Assess fitness', 'Sick note rules', 'Support', 'Return to work', 'Documentation'],
  '## Model Approach\n\n**Key:** Assess current fitness. Issue note if unfit. Discuss support (CBT, meds). Plan for return. Document reason.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established mood and function", "Explored ICE", "Risk assessment"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["Fitness for work", "Note if appropriate", "Support", "Documentation"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Empathy", "Non-judgmental"]}}'
),

('Palpitations', 'Cardiology', 'FC-008',
  'You are a GP. A 44-year-old woman, Ms. Jane Todd, has had intermittent palpitations for 3 weeks. Last a few seconds. No syncope. Stressed at work.',
  '{"name": "Ms. Jane Todd", "age": 44, "gender": "Female"}',
  '{"patient": "Ms. Jane Todd", "age": 44, "gender": "Female", "pmh": "None", "medications": "None", "allergies": "None", "social_summary": "Manager, 4 coffees/day", "family_summary": "No cardiac history"}',
  '{"opening_statement": "My heart sometimes races for a few seconds. It frightens me. Could it be my heart?", "freely_given_history": {"presenting_complaint": "Palpitations, brief.", "ice": {"ideas": "Worried about heart", "concerns": "Serious?", "expectations": "Reassurance or tests"}}, "history_on_direct_questioning": {"syncope": "No", "chest_pain": "No", "family": "No sudden death"}}',
  'Anxious. Relieved if benign explanation and simple plan.',
  'full', 720, 'easy',
  ARRAY['Benign vs serious', 'ECG', 'Caffeine and stress', 'Safety-netting'],
  '## Model Approach\n\n**Key:** Often benign (caffeine, stress). Red flags: syncope, chest pain, family history. ECG if indicated. Reassure. Safety-net.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established complaint", "Red flags", "Explored ICE"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["ECG if indicated", "Reassurance", "Safety-netting"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Empathy", "Clear explanation"]}}'
),

('Recurrent Thrush', 'Women''s Health', 'FC-009',
  'You are a GP. A 28-year-old woman, Ms. Kate Vine, has had four episodes of thrush in 6 months. Each time treated with clotrimazole. Wants long-term solution.',
  '{"name": "Ms. Kate Vine", "age": 28, "gender": "Female"}',
  '{"patient": "Ms. Kate Vine", "age": 28, "gender": "Female", "pmh": "None", "medications": "COCP", "allergies": "None", "social_summary": "Teacher", "family_summary": "None"}',
  '{"opening_statement": "I keep getting thrush. The cream works but it comes back. Is there something wrong with me?", "freely_given_history": {"presenting_complaint": "Recurrent thrush.", "ice": {"ideas": "Worried about diabetes or immune", "concerns": "Embarrassing", "expectations": "Prevention"}}, "history_on_direct_questioning": {"diabetes": "No", "antibiotics": "Occasional", "hygiene": "Normal"}}',
  'Embarrassed but articulate. Wants practical advice.',
  'full', 720, 'medium',
  ARRAY['Recurrent thrush', 'Exclude diabetes', 'Maintenance fluconazole', 'Lifestyle', 'Follow-up'],
  '## Model Approach\n\n**Key:** Exclude diabetes. Consider maintenance fluconazole (e.g. weekly 6 months). Avoid irritants. Follow-up.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established pattern", "Excluded diabetes", "Explored ICE"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["Maintenance treatment", "Lifestyle", "Follow-up"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Sensitive", "Clear advice"]}}'
),

('Elderly Fall', 'Geriatrics', 'FC-010',
  'You are a GP. An 82-year-old woman, Mrs. Olive Walsh, has had two falls in the last month. No serious injury. Lives alone. On ramipril, bendroflumethiazide, omeprazole.',
  '{"name": "Mrs. Olive Walsh", "age": 82, "gender": "Female"}',
  '{"patient": "Mrs. Olive Walsh", "age": 82, "gender": "Female", "pmh": "Hypertension, OA", "medications": "Ramipril, Bendroflumethiazide, Omeprazole", "allergies": "None", "social_summary": "Lives alone", "family_summary": "Daughter nearby"}',
  '{"opening_statement": "I have fallen twice. I am fine but my daughter is worried. I don''t want to go into a home.", "freely_given_history": {"presenting_complaint": "Falls.", "ice": {"ideas": "Old age", "concerns": "Independence", "expectations": "Check-up"}}, "history_on_direct_questioning": {"syncope": "No", "medication": "Takes all", "vision": "Cataracts", "home": "Stairs"}}',
  'Worried about independence. Reassured by falls assessment and practical advice.',
  'full', 720, 'medium',
  ARRAY['Falls assessment', 'Postural BP', 'Medication review', 'Vision', 'Safety'],
  '## Model Approach\n\n**Key:** Falls assessment. Lying/standing BP. Review diuretics/antihypertensives. Vision, home hazards. Refer to falls service if needed. Reassure about independence.',
  false, true,
  '{"domain1": {"title": "Domain 1: Data Gathering & Interpretation", "items": ["Established falls", "Medications", "Explored ICE"]}, "domain2": {"title": "Domain 2: Clinical Management (Weighted 1.5x)", "items": ["Falls assessment", "Medication review", "Referral if needed"]}, "domain3": {"title": "Domain 3: Interpersonal Skills", "items": ["Empathy", "Reassurance about independence"]}}'
);

-- FC-011 to FC-050: 40 more full cases (single INSERT)
INSERT INTO sca_cases (
  title, category, category_code, scenario, patient_info, case_notes, actor_info, actor_behaviour,
  case_type, time_limit, difficulty, key_points, model_answer, is_pro, published, marking_criteria
) VALUES
('Acne in Teenager', 'Dermatology', 'FC-011', 'You are a GP. A 16-year-old boy, Jack, has had facial acne for 6 months. Tried benzoyl peroxide. Wants something stronger.', '{"name": "Jack", "age": 16, "gender": "Male"}', '{"patient": "Jack", "age": 16, "gender": "Male", "pmh": "None", "medications": "None", "allergies": "None", "social_summary": "School", "family_summary": "None"}', '{"opening_statement": "My spots are getting worse. The gel did not help much. Can I get something stronger?", "freely_given_history": {"presenting_complaint": "Acne.", "ice": {"ideas": "Wants Roaccutane", "concerns": "Scarring", "expectations": "Clear skin"}}, "history_on_direct_questioning": {"severity": "Moderate", "topical": "Tried 3 months"}}', 'Teenager, a bit self-conscious. Wants clear plan.', 'full', 720, 'easy', ARRAY['Severity', 'Topical vs oral', 'Antibiotic vs isotretinoin', 'Expectations'], '## Model Approach\n\n**Key:** Assess severity. Topical retinoid + ab. Oral antibiotic if moderate. Isotretinoin only if severe/referral. Expectations.', false, true, '{"domain1": {"title": "Domain 1", "items": ["Established complaint", "Severity", "Explored ICE"]}, "domain2": {"title": "Domain 2", "items": ["Stepped treatment", "Referral if needed"]}, "domain3": {"title": "Domain 3", "items": ["Empathy", "Clear advice"]}}'),
('Asthma Review', 'Respiratory', 'FC-012', 'You are a GP. A 35-year-old woman, Ms. Anna Bell, is here for asthma review. Uses salbutamol 3–4 times per week. No preventer.', '{"name": "Ms. Anna Bell", "age": 35, "gender": "Female"}', '{"patient": "Ms. Anna Bell", "age": 35, "gender": "Female", "pmh": "Asthma", "medications": "Salbutamol PRN", "allergies": "None", "social_summary": "Teacher, non-smoker", "family_summary": "None"}', '{"opening_statement": "I use my blue inhaler most days. The nurse said I might need a preventer. What do you think?", "freely_given_history": {"presenting_complaint": "Frequent salbutamol use.", "ice": {"ideas": "Worried about steroids", "concerns": "Side effects", "expectations": "Clear plan"}}, "history_on_direct_questioning": {"symptoms": "Cough, wheeze", "night_waking": "Rarely", "peak_flow": "Not measured"}}', 'Cooperative. Wants to avoid attacks.', 'full', 720, 'easy', ARRAY['Control', 'Preventer', 'Technique', 'Action plan'], '## Model Approach\n\n**Key:** Assess control. Add ICS if using SABA >2/week. Check technique. Written action plan.', false, true, '{"domain1": {"title": "Domain 1", "items": ["Control", "Symptoms", "ICE"]}, "domain2": {"title": "Domain 2", "items": ["Preventer", "Action plan"]}, "domain3": {"title": "Domain 3", "items": ["Clear advice"]}}'),
('Breast Lump', 'Women''s Health', 'FC-013', 'You are a GP. A 48-year-old woman, Mrs. Carol Dean, has found a lump in her left breast 1 week ago. No pain. Periods regular.', '{"name": "Mrs. Carol Dean", "age": 48, "gender": "Female"}', '{"patient": "Mrs. Carol Dean", "age": 48, "gender": "Female", "pmh": "None", "medications": "None", "allergies": "None", "social_summary": "Office job", "family_summary": "No breast cancer"}', '{"opening_statement": "I found a lump last week. I am scared it might be cancer. What happens next?", "freely_given_history": {"presenting_complaint": "Breast lump.", "ice": {"ideas": "Worried about cancer", "concerns": "Waiting", "expectations": "Referral"}}, "history_on_direct_questioning": {"pain": "No", "nipple": "No change", "family": "None"}}', 'Anxious. Relieved by clear 2WW pathway.', 'full', 720, 'medium', ARRAY['2WW breast', 'Examination', 'Triple assessment', 'Safety-netting'], '## Model Approach\n\n**Key:** 2WW breast referral. Examine if competent. Don''t reassure without referral. Safety-net.', false, true, '{"domain1": {"title": "Domain 1", "items": ["History", "Examination", "ICE"]}, "domain2": {"title": "Domain 2", "items": ["2WW referral", "Safety-netting"]}, "domain3": {"title": "Domain 3", "items": ["Empathy", "Reassurance"]}}'),
('COPD Exacerbation', 'Respiratory', 'FC-014', 'You are a GP. A 68-year-old man, Mr. Eric Fox, has COPD. Increased cough, green sputum, breathlessness for 3 days. No fever.', '{"name": "Mr. Eric Fox", "age": 68, "gender": "Male"}', '{"patient": "Mr. Eric Fox", "age": 68, "gender": "Male", "pmh": "COPD", "medications": "Seretide, Tiotropium", "allergies": "None", "social_summary": "Ex-smoker", "family_summary": "None"}', '{"opening_statement": "I am more breathless and coughing up green phlegm. I have my rescue pack. Should I start it?", "freely_given_history": {"presenting_complaint": "Exacerbation.", "ice": {"ideas": "Infection", "concerns": "Hospital", "expectations": "Antibiotics"}}, "history_on_direct_questioning": {"fever": "No", "respiratory_rate": "Increased", "sats": "Not measured"}}', 'Breathless but coherent. Wants to avoid hospital.', 'full', 720, 'medium', ARRAY['Exacerbation', 'Antibiotics and steroids', 'Rescue pack', 'Hospital criteria'], '## Model Approach\n\n**Key:** Antibiotics + steroids if purulent. Check rescue pack. Hospital if severe. Safety-net.', false, true, '{"domain1": {"title": "Domain 1", "items": ["Severity", "Symptoms", "ICE"]}, "domain2": {"title": "Domain 2", "items": ["Antibiotics", "Steroids", "Safety-netting"]}, "domain3": {"title": "Domain 3", "items": ["Empathy"]}}'),
('Depression Follow-up', 'Mental Health', 'FC-015', 'You are a GP. A 42-year-old man, Mr. Gary Hill, started sertraline 6 weeks ago for depression. Mood a bit better but still low. No suicidal thoughts.', '{"name": "Mr. Gary Hill", "age": 42, "gender": "Male"}', '{"patient": "Mr. Gary Hill", "age": 42, "gender": "Male", "pmh": "Depression", "medications": "Sertraline 50mg", "allergies": "None", "social_summary": "Unemployed", "family_summary": "None"}', '{"opening_statement": "I am a bit better but still not right. Should I increase the dose or wait?", "freely_given_history": {"presenting_complaint": "Partial response.", "ice": {"ideas": "Wants to get better", "concerns": "Side effects", "expectations": "Dose or time"}}, "history_on_direct_questioning": {"mood": "Improved", "risk": "No SI", "sleep": "Better"}}', 'Low but engaged. Wants clear plan.', 'full', 720, 'easy', ARRAY['Response', 'Dose increase', 'Psychological', 'Safety'], '## Model Approach\n\n**Key:** Partial response – consider dose increase or wait. Psychological support. Risk assessment. Follow-up.', false, true, '{"domain1": {"title": "Domain 1", "items": ["Mood", "Risk", "ICE"]}, "domain2": {"title": "Domain 2", "items": ["Dose", "Support", "Follow-up"]}, "domain3": {"title": "Domain 3", "items": ["Empathy"]}}'),
